using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1StoryFinish {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_EnvironmentalStory/");
 public static object Reflections(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit required");var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));bool active=player.activeSelf,async=ShaderUtil.allowAsyncCompilation;var results=new List<object>();try{player.SetActive(false);ShaderUtil.allowAsyncCompilation=false;foreach(var probe in GameObject.Find("1F_AbandonedFactory").GetComponentsInChildren<ReflectionProbe>()){string path=AssetDatabase.GetAssetPath(probe.customBakedTexture);if(!path.StartsWith(E+"Textures/AE_Reflection_"))continue;var mode=probe.mode;probe.mode=ReflectionProbeMode.Baked;try{if(!Lightmapping.BakeReflectionProbe(probe,path))throw new Exception(probe.name);}finally{probe.mode=mode;}AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);results.Add(new{probe.name,path});}}finally{player.SetActive(active);ShaderUtil.allowAsyncCompilation=async;EditorSceneManager.OpenScene(s.path);}File.WriteAllText(Out+"reflections.json",JsonConvert.SerializeObject(results,Formatting.Indented));return new{probes=results.Count};}
 public static object Check(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty)throw new Exception("Saved edit required");var before=JArray.Parse(File.ReadAllText(Out+"before_transforms.json"));var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var changes=new List<string>();float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};foreach(var t in ts){string path=AnimationUtility.CalculateTransformPath(t,null);var b=before.FirstOrDefault(q=>(string)q["path"]==path);if(b==null){changes.Add(path+" added");continue;}foreach(var q in new[]{new{key="position",value=V(t.position)},new{key="local",value=V(t.localPosition)},new{key="rotation",value=V(t.eulerAngles)},new{key="scale",value=V(t.localScale)}}){var a=b[q.key].Values<float>().ToArray();if(q.value.Where((v,i)=>Mathf.Abs(v-a[i])>.00001f).Any())changes.Add(path+" "+q.key);}if((bool)b["active"]!=t.gameObject.activeSelf)changes.Add(path+" active");}
 var mats=Directory.GetFiles(E+"Materials","AE_M_*.mat").Select(p=>AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'))).Where(m=>m&&m.HasProperty("_AE_WearAmount")).Select(m=>new{m.name,mode=m.GetFloat("_AE_Mode"),wear=m.GetFloat("_AE_WearAmount"),frequency=m.GetFloat("_AE_MacroScale"),baseMap=m.GetTexture("_BaseMap")?.name,normal=m.GetTexture("_BumpMap")?.name}).ToArray();var result=new{scene=s.path,saved=!s.isDirty,playing=Application.isPlaying,transforms=ts.Length,beforeTransforms=before.Count,transformChanges=changes,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),missingMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh),missingMaterials=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),materials=mats,occlusionBytes=StaticOcclusionCulling.umbraDataSize,runInBackground=Application.runInBackground};File.WriteAllText(Out+"final_check.json",JsonConvert.SerializeObject(result,Formatting.Indented));Selection.activeGameObject=GameObject.Find("AE_C01_Walls");SceneView.lastActiveSceneView?.LookAt(new Vector3(-12,4,-14),Quaternion.Euler(8,24,0),16,false,true);return result;}
